export interface AppElements {
  form: HTMLFormElement;
  titleInput: HTMLInputElement;
  bodyInput: HTMLTextAreaElement;
  avatarInput: HTMLInputElement;
  searchInput: HTMLInputElement;
  resultsLine: HTMLParagraphElement;
  feed: HTMLElement;
