input.content:
:root {
  color-scheme: light dark;
  font-family: system-ui, sans-serif;
}

body {
  margin: 0 auto;
  max-width: 40rem;
  padding: 1.5rem 1rem 4rem;
  line-height: 1.5;
}

h1 {
  font-size: 1.5rem;
}

#note-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  border: 1px solid #8887;
  border-radius: 0.5rem;
  margin-bottom: 1.5rem;
}

#note-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.9rem;
}

#note-form input,
#note-form textarea {
  font: inherit;
  padding: 0.4rem 0.5rem;
  border: 1px solid #8887;
  border-radius: 0.35rem;
}

#note-form button {
  align-self: flex-start;
  font: inherit;
  padding: 0.5rem 1rem;
  border: 1px solid #8887;
  border-radius: 0.35rem;
  cursor: pointer;
}

.search-wrap {
  margin-bottom: 0.25rem;
}

.search-wrap label,
.search-wrap input {
  display: block;
  width: 100%;
  box-sizing: border-box;
}

.search-wrap input {
  font: inherit;
  padding: 0.4rem 0.5rem;
  border: 1px solid #8887;
  border-radius: 0.35rem;
}

#results-line {
  font-size: 0.9rem;
  color: #666;
  min-height: 1.2rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.note {
  padding: 1rem;
  border: 1px solid #8887;
  border-radius: 0.5rem;
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: 0.75rem;
  row-gap: 0.35rem;
}

.note[aria-current='true'] {
  border-color: currentColor;
  border-width: 2px;
}

.note-avatar {
  grid-row: span 2;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  object-fit: cover;
}

.note-title {
  grid-column: 2;
  font: inherit;
  font-weight: 600;
  font-size: 1.05rem;
  text-align: left;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
  justify-self: start;
}

.note-body {
  grid-column: 2;
}

.note-body a {
  color: inherit;
}

