cat > /tmp/porto-check.mjs <<'EOF'
import { chromium } from '@playwright/test';

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto('http://127.0.0.1:4599/');
await page.waitForSelector('.note');

const noteCount = await page.locator('.note').count();
console.log('note count:', noteCount);

const firstTitleHtml = await page.locator('.note .note-title').first().innerHTML();
console.log('first title html:', firstTitleHtml);

const firstBodyHtml = await page.locator('.note .note-body').first().innerHTML();
console.log('first body html:', firstBodyHtml);

// search
await page.fill('#search', 'douro');
await page.waitForTimeout(100);
console.log('results line:', await page.locator('#results-line').textContent());
console.log('filtered count:', await page.locator('.note').count());
console.log('hash after search:', await page.evaluate(() => location.hash));

await page.fill('#search', '');
await page.waitForTimeout(100);

// select a note
await page.locator('.note .note-title', { hasText: 'Livraria Lello' }).click();
console.log('hash after select:', await page.evaluate(() => location.hash));
console.log('aria-current article:', await page.locator('.note[aria-current="true"]').getAttribute('data-note-id'));

// add a note
await page.fill('#title', 'Test <b>note</b>');
await page.fill('#body', 'Hello <i>world</i>\nsecond line <a href="https://example.com">link</a>');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(100);
console.log('note count after add:', await page.locator('.note').count());
const newTitleHtml = await page.locator('.note .note-title').first().innerHTML();
console.log('new title html:', newTitleHtml);
const newBodyHtml = await page.locator('.note .note-body').first().innerHTML();
console.log('new body html:', newBodyHtml);
console.log('title input cleared:', await page.inputValue('#title'));

// reload and confirm deep link + persistence restore
await page.goto('http://127.0.0.1:4599/#q=port&note=3');
await page.waitForSelector('.note');
console.log('restored search value:', await page.inputValue('#search'));
console.log('restored results line:', await page.locator('#results-line').textContent());
console.log('restored selected id:', await page.locator('.note[aria-current="true"]').getAttribute('data-note-id'));
console.log('note count persisted (should be 7):', await page.evaluate(() => JSON.parse(localStorage.getItem('porto-notes')).length));

console.log('console/page errors:', errors);

await browser.close();
EOF
